package com.bank.java11;

import java.util.List;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public class Java11FeaturesDemo {

    public static void demonstrateAll() {

        // ═══ 1. VAR in lambda parameters (enables annotations) ═══
        // (var x, var y) -> x + y — equivalent to (x, y) -> x + y
        // But allows: (@NotNull var x) -> x.toUpperCase()
        List<String> symbols = List.of("RELIANCE", "TCS", "HDFC");
        symbols.stream()
            .map((var s) -> s.toLowerCase())  // var in lambda
            .toList();

        // ═══ 2. NEW STRING METHODS ═══
        "".isBlank();           // true (empty is blank)
        "   ".isBlank();        // true (whitespace only is blank)
        " RELIANCE ".strip();   // "RELIANCE" (Unicode-aware trim)
        " RELIANCE ".stripLeading();  // "RELIANCE "
        " RELIANCE ".stripTrailing(); // " RELIANCE"
        "TCS ".repeat(3);      // "TCS TCS TCS "
        "A\nB\nC".lines();     // Stream<String>: ["A", "B", "C"]

        // ═══ 3. PREDICATE.NOT() ═══
        List<String> nonBlank = List.of("RELIANCE", "", "TCS", "  ", "HDFC").stream()
            .filter(Predicate.not(String::isBlank))  // cleaner than s -> !s.isBlank()
            .toList();
        // [RELIANCE, TCS, HDFC]

        // ═══ 4. HTTP CLIENT (standardized) ═══
        // var client = HttpClient.newHttpClient();
        // var request = HttpRequest.newBuilder(URI.create("https://api.bank.com/rates")).build();
        // var response = client.send(request, HttpResponse.BodyHandlers.ofString());
        // Supports HTTP/2, async (sendAsync), WebSocket

        // ═══ 5. SINGLE-FILE SOURCE-CODE LAUNCH ═══
        // java HelloWorld.java  (no javac needed for single-file programs)

        // ═══ 6. EPSILON GC ═══
        // java -XX:+UseEpsilonGC — no-op GC, never collects. For benchmarks/testing.
    }
}
