package com.bank.java11;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.function.Predicate;
import static org.assertj.core.api.Assertions.*;

class Java11FeaturesTest {

    @Test void isBlank() {
        assertThat("".isBlank()).isTrue();
        assertThat("   ".isBlank()).isTrue();
        assertThat("TCS".isBlank()).isFalse();
    }

    @Test void strip() {
        assertThat(" RELIANCE ".strip()).isEqualTo("RELIANCE");
        assertThat(" RELIANCE ".stripLeading()).isEqualTo("RELIANCE ");
        assertThat(" RELIANCE ".stripTrailing()).isEqualTo(" RELIANCE");
    }

    @Test void repeat() {
        assertThat("TCS ".repeat(3)).isEqualTo("TCS TCS TCS ");
        assertThat("*".repeat(5)).isEqualTo("*****");
    }

    @Test void lines() {
        List<String> lines = "A\nB\nC".lines().toList();
        assertThat(lines).containsExactly("A", "B", "C");
    }

    @Test void predicateNot() {
        List<String> clean = List.of("A", "", "B", " ", "C").stream()
            .filter(Predicate.not(String::isBlank))
            .toList();
        assertThat(clean).containsExactly("A", "B", "C");
    }

    @Test void varInLambda() {
        // var in lambda enables annotations — functionally same as without var
        List<String> result = List.of("reliance", "tcs").stream()
            .map((var s) -> s.toUpperCase())
            .toList();
        assertThat(result).containsExactly("RELIANCE", "TCS");
    }
}
