package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.function.Predicate;
import static org.assertj.core.api.Assertions.assertThat;

class Java11FeaturesTest {

    @Test
    void stringLinesStripPredicateNot() {
        String report = "  SAV2001:50000  

  CUR3001:25000  
   ";

        List<String> rows = report.lines()                     // Stream<String>
            .map(String::strip)                                // Unicode-aware trim
            .filter(Predicate.not(String::isBlank))            // drop blank lines
            .toList();

        assertThat(rows).containsExactly("SAV2001:50000", "CUR3001:25000");
        assertThat("=".repeat(3)).isEqualTo("===");            // String.repeat
    }
}
